parameters.jsCode:
// =====================================================================
// Check reply: checks each AI explanation and builds the final report
// =====================================================================

// ---------- settings ----------
const DEBUG = true;                  // false for the live site: hides raw_reply, problems and notes
const NOVELTY_LIMIT = 0.7;           // reject an AI explanation if more than this share of its key words is not in the guidance
const SENTENCE_NOVELTY_LIMIT = 0.6;  // reject if any single sentence has more than this share of key words not in the guidance
const AI_TITLES = false;             // true = use the AI's titles when they pass the checks; false = always use the standard titles
const TRUST_ENGINE_COUNT = false;    // true = summary uses the engine's findings_scored; false = summary uses the count of scored findings
const SABOTAGE = 'none';           // TESTING ONLY: 'none' | 'skip' | 'banned' | 'invent' | 'jargon' | 'one_sentence' | 'number' | 'not_json'

// ---------- helpers ----------
const STOP = new Set(('this that these those with without from into onto over under about than then they them their there here what when where which while also only just more less some any each every other another such very much many most could would should might will does have has had been being were your yours').split(' '));
function isStr(x) { return typeof x === 'string' && x.trim() !== ''; }
function isNum(x) { return typeof x === 'number' && isFinite(x); }
function numOrNull(x) { return isNum(x) ? x : null; }
function cap(s) { s = String(s || '').trim(); return s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : s; }
function norm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function stem(w) { return w.replace(/(ing|ed|es|s|ly)$/, ''); }
function keyWords(s) { return (String(s || '').toLowerCase().match(/[a-z][a-z-]{3,}/g) || []).filter(w => !STOP.has(w)).map(stem); }
function isDevLine(t) { return /stage 2|scenario rule|aggregation policy/i.test(String(t)); }
function cleanLimits(arr) { return (Array.isArray(arr) ? arr : []).filter(t => isStr(t) && !isDevLine(t)); }
function sentences(s) { return String(s).split(/(?<=[.!?])\s+/).filter(x => x.trim().length > 0); }

// risk breakdown for one finding and one view (null when the finding is not scored)
function riskDetail(p) {
  if (!p || !isNum(p.risk_score) || !isStr(p.risk_level)) return null;
  const c = p.cia || {}, lf = p.likelihood_factors || {};
  return {
    level: cap(p.risk_level),
    score: p.risk_score,
    likelihood: numOrNull(p.likelihood),
    impact: numOrNull(p.impact),
    likelihood_factors: {
      discoverability: numOrNull(lf.discoverability),
      exploitability: numOrNull(lf.exploitability),
      reproducibility: numOrNull(lf.reproducibility)
    },
    cia: {
      confidentiality: numOrNull(c.confidentiality),
      integrity: numOrNull(c.integrity),
      availability: numOrNull(c.availability)
    }
  };
}

// ---------- standard text (also the source of truth for owner actions) ----------
// key = a technical term the technical explanation must contain
const GUIDE = {
  hostname_detected: {
    title: "Website name detected", plainTitle: "Website name detected",
    plain: "This only records the website's name. It was not scored.", technical: "", owner: null, key: null
  },
  redirect_detected: {
    title: "Redirect detected", plainTitle: "Redirect detected",
    plain: "The site sent the visitor to another address, and the scanner did not check where it leads. It was not scored.", technical: "", owner: null, key: null
  },
  missing_csp: {
    title: "Missing Content-Security-Policy", plainTitle: "No rules for trusted content",
    plain: "A Content-Security-Policy is a setting that tells the browser which sources of scripts and content the site trusts. Without it, the browser has fewer built-in limits if untrusted code ever ends up on the page.",
    technical: "The CSP response header restricts the sources of scripts, styles and frames, which limits the impact of injected scripts.",
    owner: "Add a Content-Security-Policy header listing the sources the site trusts.",
    key: /content-security-policy|\bcsp\b/i
  },
  weak_x_content_type_options: {
    title: "Weak X-Content-Type-Options setting", plainTitle: "Browser may guess file types",
    plain: "This setting tells the browser not to guess what type a file is. Without it, a browser may treat a file as something other than what the server said.",
    technical: "Without X-Content-Type-Options: nosniff, browsers may MIME-sniff a response and treat it as a different content type than declared.",
    owner: "Add the header X-Content-Type-Options set to nosniff.",
    key: /nosniff|x-content-type-options|mime/i
  },
  missing_or_weak_hsts: {
    title: "Missing or weak HSTS", plainTitle: "Secure connection not enforced",
    plain: "This setting tells browsers to always use the secure version of the site. Without it, someone on the same network could interfere with a visit that starts on the insecure version.",
    technical: "Without Strict-Transport-Security, a first or downgraded plain HTTP request can be intercepted (SSL stripping). A long max-age makes browsers upgrade to HTTPS.",
    owner: "Add a Strict-Transport-Security header with a long max-age.",
    key: /strict-transport-security|\bhsts\b|ssl stripping|max-age/i
  },
  missing_frame_protection: {
    title: "Missing frame protection", plainTitle: "No protection against hidden frames",
    plain: "This setting stops other websites from showing this site inside a hidden frame on their page. Without it, a malicious page could trick a visitor into clicking something on this site without realising it.",
    technical: "Without X-Frame-Options or a CSP frame-ancestors rule, other origins can embed the page in a frame, which enables clickjacking.",
    owner: "Add an X-Frame-Options header or a CSP frame-ancestors rule.",
    key: /x-frame-options|frame-ancestors|clickjacking/i
  }
};
const GENERIC = 'website websites site page pages browser browsers visitor visitors people person someone user users setting settings help helps protect protects make makes keep keeps stop stops allow allows means mean missing weak data information content secure security connection connections version owner owners add added file files code box display displaying show showing here';

// ---------- checks ----------
const BANNED = [
  /vulnerab/i, /susceptib/i, /exploit/i, /man-in-the-middle/i,
  /\bunsafe\b/i, /\bsafe\b/i, /\bno (specific )?risks?\b/i, /does not indicate/i,
  /phishing/i, /\bsteal/i, /\bstolen\b/i, /\bhack/i, /malware/i, /\bvirus/i, /identity theft/i,
  /credit card/i, /\bbank/i, /password/i, /guarantee/i,
  /\battacker/i, /plain text/i,
  /needs[_ ]rule/i, /stage 2/i, /visitor action|owner action/i,
  /ignore (all|any|previous|the above)/i, /\binstruction/i,
  /\bscore/i, /risk level/i, /\b(low|medium|high|critical)[ -](risk|severity)\b/i
];
// beginner only
const JARGON = /\b(mime|sniff\w*|nosniff|ssl|tls|stripping|clickjack\w*|frame-ancestors|max-age|downgrad\w*|origins?|response header|content type|injected|attack\w*)\b/i;
const TITLE_JARGON = /content-security-policy|strict-transport-security|x-content-type-options|x-frame-options|\bhsts\b|\bcsp\b/i;

// ---------- inputs ----------
const webhookItem = $('Webhook').first();
const scan = (webhookItem && webhookItem.json && webhookItem.json.body) || {};
const a = scan.assessment || {};
const persp = a.perspectives || {};
const visitor = persp.visitor || {};
const owner = persp.website_owner || {};
const inputFindings = Array.isArray(a.findings) ? a.findings : [];

const levelRaw = String((scan.report_preferences && scan.report_preferences.literacy_level) || 'unspecified').toLowerCase();
const technical = /technical|advanced|expert/.test(levelRaw);
const literacy = technical ? 'technical' : 'beginner';

const problems = [];
const notes = [];

// ---------- counts and overall risk, from the data ----------
const countScored = inputFindings.filter(f => {
  const p = f.perspectives || {};
  return (p.visitor && isNum(p.visitor.risk_score)) || (p.website_owner && isNum(p.website_owner.risk_score));
}).length;
const engineReceived = isNum(visitor.findings_received) ? visitor.findings_received : null;
const engineScored = isNum(visitor.findings_scored) ? visitor.findings_scored : null;
const received = (TRUST_ENGINE_COUNT && engineReceived !== null) ? engineReceived : inputFindings.length;
const scored = (TRUST_ENGINE_COUNT && engineScored !== null) ? engineScored : countScored;
if (engineReceived !== null && engineReceived !== inputFindings.length) notes.push('findings_received (' + engineReceived + ') differs from the findings list (' + inputFindings.length + ')');
if (engineScored !== null && engineScored !== countScored) notes.push('findings_scored (' + engineScored + ') differs from the scored findings counted (' + countScored + ')');

function overall(p) {
  const r = p && p.overall_risk;
  return (r && isStr(r.risk_level) && isNum(r.risk_score)) ? { level: cap(r.risk_level), score: r.risk_score } : null;
}
const vRisk = overall(visitor);
const oRisk = overall(owner);
const NOT_SCORED = 'Not scored yet, because scoring rules are not available.';
const NO_FINDINGS = 'No issues were found in the checks that were run.';
function riskStatus(r) {
  if (r) return 'Overall risk level: ' + r.level + ' (score ' + r.score + ' out of 25).';
  return inputFindings.length === 0 ? NO_FINDINGS : NOT_SCORED;
}

// highest per-finding level for one view (used when the overall level is missing)
const LEVEL_RANK = { low: 1, medium: 2, high: 3, critical: 4 };
function maxLevel(view) {
  let best = null;
  inputFindings.forEach(f => {
    const p = (f.perspectives || {})[view];
    if (p && isNum(p.risk_score) && isStr(p.risk_level)) {
      const l = cap(p.risk_level);
      if (!best || (LEVEL_RANK[l.toLowerCase()] || 0) > (LEVEL_RANK[best.toLowerCase()] || 0)) best = l;
    }
  });
  return best;
}

// ---------- summary, written by code ----------
let summary;
if (inputFindings.length === 0) {
  summary = '0 findings were reviewed. No security issues were found in the checks that were run.';
} else {
  const first = received + (received === 1 ? ' finding was' : ' findings were') + ' reviewed and ' + scored + ' ' + (scored === 1 ? 'was' : 'were') + ' scored.';
  let second;
  if (vRisk && oRisk) second = 'The overall risk is ' + vRisk.level + ' for visitors and ' + oRisk.level + ' for the website owner.';
  else if (vRisk) second = 'The overall risk for visitors is ' + vRisk.level + '. The risk for the website owner has not been scored yet.';
  else if (oRisk) second = 'The overall risk for the website owner is ' + oRisk.level + '. The risk for visitors has not been scored yet.';
  else second = 'A risk level cannot be given yet, because scoring rules are not available.';
  summary = first + ' ' + second;
}

// ---------- limitations, copied from the data without developer-only lines ----------
const limitations = cleanLimits(a.limitations);

// ---------- actions, written by code ----------
const ownerSet = [];
inputFindings.forEach(f => {
  const g = GUIDE[f.id];
  if (g && g.owner && !ownerSet.includes(g.owner)) ownerSet.push(g.owner);
});
const ownerActions = ownerSet.length
  ? ownerSet.map(t => technical ? t : 'Ask your website developer to ' + t.charAt(0).toLowerCase() + t.slice(1))
  : ['There is nothing specific for the website owner to fix based on these findings.'];
const visitorLevel = vRisk ? vRisk.level : maxLevel('visitor');
if (!vRisk && visitorLevel) notes.push('visitor action based on the highest finding-level visitor risk (' + visitorLevel + '), because the overall visitor risk is missing');
const visitorAction = (visitorLevel && /^(High|Critical)$/.test(visitorLevel))
  ? 'Avoid entering passwords or personal details on this website until its owner has fixed these issues.'
  : 'There is nothing specific for a visitor to do because of these findings.';

// ---------- read and parse the model reply ----------
const inItem = $input.first();
const resp = (inItem && inItem.json) || {};
const usage = resp.usage || {};
if (resp.error) {
  const m = typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error));
  problems.push('Model call failed: ' + String(m).slice(0, 200));
}
const choice = resp.choices && resp.choices[0];
const modelRaw = choice && choice.message && typeof choice.message.content === 'string' ? choice.message.content : '';
if (choice && choice.finish_reason === 'length') problems.push('Reply was cut off (max_tokens reached)');

// TESTING ONLY: replace the reply with plain text
const raw = (SABOTAGE === 'not_json' && modelRaw) ? 'Sure! Here is the report you asked for. Everything looks fine.' : modelRaw;

function parseJson(text) {
  if (!isStr(text)) return null;
  const t = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(t); } catch (e) {}
  const s = t.indexOf('{'), e2 = t.lastIndexOf('}');
  if (s !== -1 && e2 > s) { try { return JSON.parse(t.slice(s, e2 + 1)); } catch (e) {} }
  return null;
}
const parsed = parseJson(raw);
if (!raw) problems.push('No reply from the model');
else if (parsed === null) problems.push('Reply was not valid JSON');

let aiList = [];
if (Array.isArray(parsed)) aiList = parsed;
else if (parsed && Array.isArray(parsed.findings)) aiList = parsed.findings;
else if (parsed && parsed.findings && typeof parsed.findings === 'object') {
  aiList = Object.keys(parsed.findings).map(k => Object.assign({ finding_ref: k }, parsed.findings[k]));
} else if (parsed) problems.push('Reply had no findings list');

// TESTING ONLY: damage the second AI entry before the checks run
if (SABOTAGE !== 'none') notes.push('SABOTAGE TEST ACTIVE: ' + SABOTAGE);
if (SABOTAGE !== 'none' && SABOTAGE !== 'not_json' && aiList.length) {
  const target = aiList[Math.min(1, aiList.length - 1)];
  if (SABOTAGE === 'skip') {
    aiList = aiList.filter(g => g !== target);
  } else if (target && typeof target === 'object' && isStr(target.explanation)) {
    if (SABOTAGE === 'banned') target.explanation += ' Attackers could steal your passwords.';
    if (SABOTAGE === 'invent') target.explanation += ' A similar problem caused a famous data breach at a large company.';
    if (SABOTAGE === 'jargon') target.explanation += ' This allows MIME-sniffing and SSL stripping.';
    if (SABOTAGE === 'number') target.explanation += ' This affects about 40 percent of websites.';
    if (SABOTAGE === 'one_sentence') target.explanation = sentences(target.explanation)[0];
  }
}

// index the AI entries by finding_ref (and by id, only when an id is unique on both sides)
const byRef = {}, byId = {}, aiIdCount = {}, inIdCount = {};
inputFindings.forEach(f => { inIdCount[f.id] = (inIdCount[f.id] || 0) + 1; });
aiList.forEach(g => {
  if (!g || typeof g !== 'object') return;
  const ref = isStr(g.finding_ref) ? g.finding_ref.trim() : (isStr(g.ref) ? g.ref.trim() : null);
  if (ref && !byRef[ref]) byRef[ref] = g;
  if (isStr(g.id)) { aiIdCount[g.id] = (aiIdCount[g.id] || 0) + 1; if (!byId[g.id]) byId[g.id] = g; }
});
const knownRefs = new Set(inputFindings.map(f => f.finding_ref));
Object.keys(byRef).forEach(r => { if (!knownRefs.has(r)) notes.push('Ignored an AI entry for an unknown finding: ' + r.slice(0, 40)); });

// ---------- per-finding checks ----------
function novelty(text, allowedSet) {
  const w = keyWords(text);
  if (!w.length) return { ratio: 0, count: 0 };
  return { ratio: w.filter(x => !allowedSet.has(x)).length / w.length, count: w.length };
}
function copiesEvidence(ex, ev) { const e = norm(ev); return e.length > 25 && norm(ex).includes(e); }
function stdTitle(f) {
  const g = GUIDE[f.id];
  if (g) return technical ? g.title : (g.plainTitle || g.title);
  return /^[a-z0-9_]{1,40}$/i.test(String(f.id || '')) ? cap(String(f.id).replace(/_/g, ' ')) : 'Other finding';
}
function cleanTitle(t) {
  if (!isStr(t)) return null;
  const s = t.trim().replace(/[.!]+$/, '');
  if (s.split(/\s+/).length > 8 || s.length > 70) return null;
  if (BANNED.some(re => re.test(s))) return null;
  if (!technical && (JARGON.test(s) || TITLE_JARGON.test(s))) return null;
  return s;
}
function rejectReason(e, f, g) {
  if (!e) return 'AI wrote no entry';
  if (!isStr(e.explanation)) return 'AI entry had no explanation';
  const ex = e.explanation.trim();
  if (ex.length < 30) return 'explanation too short';
  if (ex.length > 700) return 'explanation too long';
  const parts = sentences(ex);
  if (!technical && parts.length < 2) return 'beginner explanation needs 2 sentences';
  if (!technical && parts.length > 2) return 'beginner explanation has extra sentences';
  if (technical && parts.length < 3) return 'technical explanation needs 3 sentences';
  if (technical && parts.length > 4) return 'technical explanation has extra sentences';
  for (const re of BANNED) { if (re.test(ex)) return 'banned wording: ' + re.source; }
  if (/\d/.test(ex)) return 'explanation contains a number';
  if (!technical && JARGON.test(ex)) return 'technical term in a beginner explanation';
  if (technical && g.key && !g.key.test(ex)) return 'technical explanation is missing the key technical detail';
  if (copiesEvidence(ex, f.evidence)) return 'copied the scanner evidence';
  const allowed = new Set(keyWords(g.plain + ' ' + (technical ? g.technical : '') + ' ' + g.title + ' ' + g.plainTitle + ' ' + GENERIC));
  const whole = novelty(ex, allowed);
  if (whole.count >= 8 && whole.ratio > NOVELTY_LIMIT) return 'too much content not in the guidance (' + Math.round(whole.ratio * 100) + '% new words)';
  for (const s of parts) {
    const n = novelty(s, allowed);
    if (n.count >= 4 && n.ratio > SENTENCE_NOVELTY_LIMIT) return 'a sentence adds content not in the guidance (' + Math.round(n.ratio * 100) + '% new words): ' + s.slice(0, 80);
  }
  return null;
}

// one finding in the final report: same fields whichever source is used
function buildEntry(f, title, explanation, source) {
  const p = f.perspectives || {};
  return {
    finding_ref: f.finding_ref,
    title: title,
    category: isStr(f.category) ? f.category : null,
    scanner_severity: f.scanner_severity ?? null,
    explanation: explanation,
    limitations: cleanLimits(f.limitations),
    visitor_risk: riskDetail(p.visitor),
    owner_risk: riskDetail(p.website_owner),
    source: source
  };
}
function standardEntry(f) {
  const g = GUIDE[f.id];
  let text;
  if (g) text = (technical && g.technical) ? g.plain + ' ' + g.technical : g.plain;
  else text = 'The scanner recorded this: ' + (isStr(f.evidence) ? f.evidence.trim().slice(0, 300) : 'No details were provided.');
  return buildEntry(f, stdTitle(f), text, 'standard');
}

// ---------- build the findings ----------
const findingsOut = [];
let aiUsed = 0, eligible = 0;
inputFindings.forEach(f => {
  const g = GUIDE[f.id];
  const isInfo = String(f.scanner_severity || '').toLowerCase() === 'info';
  if (isInfo || !g || !isStr(g.technical)) {
    findingsOut.push(standardEntry(f));
    notes.push(f.finding_ref + ': standard text (' + (isInfo ? 'info finding, by design' : 'no guidance for id ' + f.id) + ')');
    return;
  }
  eligible++;
  let e = byRef[f.finding_ref];
  if (!e && inIdCount[f.id] === 1 && aiIdCount[f.id] === 1) e = byId[f.id];
  const why = rejectReason(e, f, g);
  if (why) {
    findingsOut.push(standardEntry(f));
    notes.push(f.finding_ref + ': standard text (' + why + ')');
    return;
  }
  aiUsed++;
  const title = AI_TITLES ? (cleanTitle(e.title) || stdTitle(f)) : stdTitle(f);
  findingsOut.push(buildEntry(f, title, e.explanation.trim(), 'ai'));
});

// ---------- status ----------
let status;
if (!parsed) status = 'fallback';
else if (eligible === 0 || aiUsed === eligible) status = 'ok';
else if (aiUsed > 0) status = 'partial';
else status = 'standard';

// ---------- output ----------
const out = {
  scan_id: scan.scan_id ?? null,
  status: status,
  report: {
    url: (a.scan && isStr(a.scan.url)) ? a.scan.url : null,
    summary: summary,
    literacy_level: literacy,
    findings: findingsOut,
    visitor_view: { risk_status: riskStatus(vRisk), recommended_actions: [visitorAction] },
    website_owner_view: { risk_status: riskStatus(oRisk), recommended_actions: ownerActions },
    limitations: limitations
  }
};
out.debug = DEBUG
  ? {
      problems: problems,
      notes: notes,
      ai_entries_used: aiUsed,
      ai_entries_expected: eligible,
      raw_reply: raw,
      meta: {
        model: resp.model ?? null,
        prompt_tokens: usage.prompt_tokens ?? null,
        completion_tokens: usage.completion_tokens ?? null,
        cost: usage.cost ?? null
      }
    }
  : { ai_entries_used: aiUsed, ai_entries_expected: eligible };

return [{ json: out }];
